import sys
import threading

def main():
    m, x = map(int, input().split())

    def min_traps(n):
        # returns minimal number of elements needed for a set S
        # s.t. for any x in Z_n, there is some s in S and some k>=0 with x * y^k ≡ s mod n
        # solution is the minimal number of generators of Z_n^* (product of min_traps for each prime power factor)
        res = 1
        d = 2
        N = n
        while d * d <= n:
            if n % d == 0:
                cnt = 0
                while n % d == 0:
                    n //= d
                    cnt += 1
                if d == 2:
                    if cnt == 1:
                        k = 1
                    elif cnt == 2:
                        k = 2
                    else:
                        k = 2
                else:
                    if cnt == 1:
                        k = 1
                    else:
                        k = d ** (cnt - 1)
                res *= k
            d += 1
        if n > 1:
            res *= 1
        return N - res

    print(min_traps(m))

threading.Thread(target=main).start()
