import sys
import math

def is_power_of_two(x):
    return x and (x & (x - 1)) == 0

def solve(n):
    answers = set()
    # For round robin ending:
    # For odd k >=3, k*(k-1)//2 == n => k^2 - k - 2n = 0
    # k = (1 + sqrt(1+8n)) // 2
    D = 1 + 8 * n
    sq = int(math.isqrt(D))
    for d in range(sq-2, sq+3):
        if d > 0 and d*d == D:
            k = (1 + d)//2
            if k*(k-1)//2 == n and k >= 3:
                answers.add(k)
    # For power of two ending:
    # n = k - 1, k = n+1 is power of two, k >= 2
    if n + 1 >= 2 and is_power_of_two(n + 1):
        answers.add(n + 1)
    if not answers:
        print(-1)
    else:
        for ans in sorted(answers):
            print(ans)

n = int(sys.stdin.readline())
solve(n)
