from sys import stdin
import threading

def main():
    import sys

    sys.setrecursionlimit(1 << 25)
    n, T = map(int, stdin.readline().split())
    songs = []
    for _ in range(n):
        t, g = map(int, stdin.readline().split())
        songs.append((t, g))
    MOD = 10 ** 9 + 7

    # dp[mask][last_gen][sum]: number of ways
    dp = [{} for _ in range(1 << n)]
    # last_gen: 0 - no previous, 1,2,3 for genres

    # start: no songs selected, no last genre, time 0
    dp[0][(0, 0)] = 1
    for mask in range(1 << n):
        for (last_gen, s), ways in dp[mask].items():
            for ni in range(n):
                if not (mask & (1 << ni)):
                    t2, g2 = songs[ni]
                    if g2 == last_gen:
                        continue
                    s2 = s + t2
                    if s2 > T:
                        continue
                    nmask = mask | (1 << ni)
                    key = (g2, s2)
                    if key in dp[nmask]:
                        dp[nmask][key] = (dp[nmask][key] + ways) % MOD
                    else:
                        dp[nmask][key] = ways % MOD

    ans = 0
    for mask in range(1 << n):
        for (last_gen, s), ways in dp[mask].items():
            if s == T:
                ans = (ans + ways) % MOD
    print(ans)

threading.Thread(target=main).start()
