def main():
    import sys
    import threading

    def solve():
        n, k = map(int, sys.stdin.readline().split())

        def count(y):
            if y > n:
                return 0
            res = 0
            if y % 2 == 1:
                x = y
                while x <= n:
                    res += min(x, n - x + 1)
                    x <<= 1
            else:
                x = y
                while x <= n:
                    res += min(x // 2, n - x + 1)
                    x <<= 1
            return res

        ans = 1

        # Odd y
        l, r = 1, n
        while l <= r:
            mid = (l + r) // 2
            m = mid if mid % 2 == 1 else mid - 1
            if m < 1:
                r = mid - 1
                continue
            c = count(m)
            if c >= k:
                ans = max(ans, m)
                l = mid + 1
            else:
                r = mid - 1

        # Even y
        l, r = 2, n
        while l <= r:
            mid = (l + r) // 2
            m = mid if mid % 2 == 0 else mid - 1
            if m < 2:
                r = mid - 1
                continue
            c = count(m)
            if c >= k:
                ans = max(ans, m)
                l = mid + 1
            else:
                r = mid - 1

        print(ans)

    threading.Thread(target=solve).start()
