min_row = min(i for i, j in black_cells)
max_row = max(i for i, j in black_cells)
min_col = min(j for i, j in black_cells)
max_col = max(j for i, j in black_cells)

height = max_row - min_row + 1
width = max_col - min_col + 1

side = max(height, width)

if side > n or side > m:
    print(-1)
    exit(0)

# Build prefix sum of black cells
prefix = [[0] * (m + 1) for _ in range(n + 1)]
for i in range(n):
    for j in range(m):
        prefix[i + 1][j + 1] = (
            prefix[i][j + 1] +
            prefix[i + 1][j] -
            prefix[i][j] +
            (1 if grid[i][j] == 'B' else 0)
        )

def get_sum(x1, y1, x2, y2):
    # sum of rectangle from (x1, y1) to (x2, y2), inclusive, 0-based
    return (
        prefix[x2 + 1][y2 + 1]
        - prefix[x1][y2 + 1]
        - prefix[x2 + 1][y1]
        + prefix[x1][y1]
    )

min_to_paint = float('inf')
for r in range(0, n - side + 1):
    for c in range(0, m - side + 1):
        # check if the given square covers all initial black cells
        if r <= min_row and max_row < r + side and c <= min_col and max_col < c + side:
            current_black_in_square = get_sum(r, c, r + side - 1, c + side - 1)
