n = int(input())
cubes = [list(map(int, input().split())) for _ in range(n)]

# For fast lookup, save each cube's digits as sets
cube_sets = [set(cube) for cube in cubes]

def can_make(num):
    digits = list(map(int, str(num)))
    if len(digits) > n:
        return False
    indices = list(range(n))
    # Try all subsets of n cubes of correct size (may not use all cubes)
    for used_cubes in combinations(indices, len(digits)):
        # Try all permutations (cube ordering)
        for cubes_order in permutations(used_cubes):
            if all(d in cube_sets[cubes_order[i]] for i, d in enumerate(digits)):
                return True
    return False

x = 1
while True:
    if can_make(x):
        x += 1
    else:
        print(x-1 if x > 1 else 0)
        break
