    print("NO")
    exit(0)

# Find position from the right where a[i]='0' and a[i+1]='0'
pair_pos = -1
for i in range(n-2):
    if a[i] == '0' and a[i+1] == '0':
        pair_pos = i
if pair_pos == -1:
    # Simply nest to the right ((...)->(1->0))
    res = a[0]
    for i in range(1, n):
        res = "(" + res + "->" + a[i] + ")"
    print("YES")
    print(res)
else:
    # construct (((a1->a2->...->ai)->(ai+1))->(ai+2->...))
    left = ""
    for i in range(pair_pos):
        if i == 0:
            left = a[0]
        else:
            left = "(" + left + "->" + a[i] + ")"
    if pair_pos != 0:
        left = "(" + left + "->" + a[pair_pos] + ")"
    else:
        left = a[0]

    mid = a[pair_pos+1]
    right = ""
    for i in range(pair_pos+2, n):
        if right == "":
            right = a[i]
        else:
            right = right + "->" + a[i]
    if right != "":
        right = "(" + right + ")"
        expr = "(" + left + "->" + "(" + mid + "->" + right + "))"
    else:
        expr = "(" + left + "->" + mid + ")"
    print("YES")
    print(expr)
